import{c as e,Q as r,j as a,m as o}from"./chunks/framework.rWdQudnF.js";const u=JSON.parse('{"title":"4+1视图与架构文档化","description":"","frontmatter":{"title":"4+1视图与架构文档化"},"headers":[],"relativePath":"综合知识/架构设计/架构设计方法/4+1视图与架构文档化.md","filePath":"综合知识/架构设计/架构设计方法/4+1视图与架构文档化.md","lastUpdated":null}'),d={name:"综合知识/架构设计/架构设计方法/4+1视图与架构文档化.md"};function n(l,t,s,i,h,c){return r(),a("div",null,[...t[0]||(t[0]=[o('<blockquote><p>4+1 视图和多视角是架构描述的核心方法，选择题高频考察视图与关注点的对应。</p></blockquote><h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[ ] 4+1 视图：逻辑/过程/开发/物理/场景</li><li>[ ] &quot;1&quot; = 统一场景（Use Case）</li><li>[ ] 视图 vs 视角</li><li>[ ] 静态视角 vs 动态视角 vs 配置视角</li><li>[ ] EEE 1471-2000 标准</li></ul><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="_4-1-视图模型" tabindex="-1">4+1 视图模型 <a class="header-anchor" href="#_4-1-视图模型" aria-label="Permalink to &quot;4+1 视图模型&quot;">​</a></h3><blockquote><p>核心思想：<strong>关注点分离</strong>。多视图从不同角度描述软件体系结构。</p></blockquote><table tabindex="0"><thead><tr><th>视图</th><th>作用</th><th>关注点</th></tr></thead><tbody><tr><td><strong>逻辑视图</strong></td><td>描述对象模型，记录设计元素的功能和概念接口</td><td>功能需求（用户视角）</td></tr><tr><td><strong>过程视图</strong></td><td>捕捉<strong>并发和同步</strong>特性</td><td>系统行为特性（动态视角）</td></tr><tr><td><strong>开发视图</strong></td><td>描述开发环境中软件的<strong>静态组织结构</strong></td><td>模块组织</td></tr><tr><td><strong>物理视图</strong></td><td>描述软件到硬件的映射</td><td>部署拓扑</td></tr><tr><td><strong>场景（+1）</strong></td><td><strong>统一场景</strong>，验证其他视图一致性</td><td>统一串联</td></tr></tbody></table><blockquote><p>⚠️ &quot;4+1&quot; 中的 &quot;1&quot; = <strong>统一场景（Use Case）</strong></p></blockquote><h3 id="视角与视图" tabindex="-1">视角与视图 <a class="header-anchor" href="#视角与视图" aria-label="Permalink to &quot;视角与视图&quot;">​</a></h3><table tabindex="0"><thead><tr><th>视角</th><th>关注点</th><th style="text-align:center;">能否判断质量特性</th></tr></thead><tbody><tr><td><strong>静态视角</strong>（逻辑视图）</td><td>功能组织</td><td style="text-align:center;">✅</td></tr><tr><td><strong>动态视角</strong>（过程视图）</td><td>并发行为 → 系统行为特性</td><td style="text-align:center;">✅</td></tr><tr><td><strong>配置视角</strong>（部署视图）</td><td>软件到硬件的映射</td><td style="text-align:center;">❌</td></tr></tbody></table><blockquote><p>🎯 四个视图：逻辑视图、进程视图、实现视图、<strong>配置视图</strong></p></blockquote><h3 id="ansi-ieee-1471-2000-标准" tabindex="-1">ANSI/IEEE 1471-2000 标准 <a class="header-anchor" href="#ansi-ieee-1471-2000-标准" aria-label="Permalink to &quot;ANSI/IEEE 1471-2000 标准&quot;">​</a></h3><ul><li>使用<strong>视图（View）</strong> 描述软件架构模型</li><li>使用<strong>视角（Viewpoint）</strong> 描述某一利益相关人关注的方面</li><li>架构描述 = 对所有利益相关人关注点的响应和回答</li></ul><h2 id="练习题" tabindex="-1">练习题 <a class="header-anchor" href="#练习题" aria-label="Permalink to &quot;练习题&quot;">​</a></h2><p>参见 <a href="./.html">架构师-备考 综合知识-架构设计-架构设计方法 概述#练习题</a>（Q3, Q10, Q11, Q14, Q15, Q16, Q17 等）</p>',15)])])}const _=e(d,[["render",n]]);export{u as __pageData,_ as default};
